package dao; import java.sql.*; import negocio.EventoComunidad; public class EventoComunidadDAOMySQL implements EventoComunidadDAO { public void guardar(Connection c,EventoComunidad v){v.validar();String q="INSERT INTO comunidad_eventos(tipo,convocatoria_id,solicitud_id,actor_cliente_id,actor_perfil_id,detalle_json,fecha_evento) VALUES(?,?,?,?,?,?,?)";try(PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){s.setString(1,v.getTipo().name());n(s,2,v.getConvocatoriaId());n(s,3,v.getSolicitudId());n(s,4,v.getActorClienteId());n(s,5,v.getActorPerfilId());s.setString(6,v.getDetalleJson());if(v.getFechaEvento()==null)s.setNull(7,Types.TIMESTAMP);else s.setTimestamp(7,Timestamp.valueOf(v.getFechaEvento()));s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())v.setId(r.getLong(1));}}catch(SQLException e){throw new RuntimeException("No se pudo registrar el evento de Comunidad.",e);}} private void n(PreparedStatement s,int i,Long v)throws SQLException{if(v==null)s.setNull(i,Types.BIGINT);else s.setLong(i,v);}}
